document.getElementById('accountForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const editId=document.getElementById('accountEditId').value;const name=document.getElementById('accountName').value.trim();if(!name)return;if(editId){const a=state.accounts.find(x=>x.id===editId);const desired=Number(document.getElementById('accountCurrent').value||0);a.name=name;a.type=document.getElementById('accountType').value;a.currency=document.getElementById('accountCurrency').value;a.logo=pendingAccountLogo||null;a.logoEmoji=pendingAccountEmoji||'';a.opening=0;const transactionEffect=accountBalance(a);a.opening=desired-transactionEffect}else{state.accounts.push({id:id(),name,type:document.getElementById('accountType').value,currency:document.getElementById('accountCurrency').value,opening:Number(document.getElementById('accountOpening').value||0),logo:pendingAccountLogo||null,logoEmoji:pendingAccountEmoji||''})}save()});

document.getElementById('txDate').value=today();document.getElementById('txForm').addEventListener('submit',e=>{e.preventDefault();if(!state.accounts.length){alert('Add an account first.');return}const amount=Number(document.getElementById('txAmount').value);const accountId=document.getElementById('txAccount').value;const toAccountId=document.getElementById('txToAccount').value;if(txType==='transfer'&&accountId===toAccountId){alert('Choose two different accounts.');return}const category=txType==='transfer'?'Transfer':document.getElementById('txCategory').value,date=document.getElementById('txDate').value,note=document.getElementById('txNote').value.trim();const duplicate=state.transactions.find(t=>t.type===txType&&Number(t.amount)===amount&&t.accountId===accountId&&t.category===category&&t.date===date&&(!t.createdAt||Date.now()-Number(t.createdAt)<15*60*1000));if(duplicate&&!confirm('This looks like a duplicate transaction. Save it anyway?'))return;const tx={id:id(),type:txType,amount,accountId,toAccountId:txType==='transfer'?toAccountId:null,category,date,note,createdAt:Date.now()};state.transactions.push(tx);if(document.getElementById('txSaveFavorite').checked&&txType!=='transfer'){state.favorites.push({id:id(),type:txType,amount,accountId,category,note})}save();e.target.reset();document.getElementById('txDate').value=today();renderCategoryOptions();setScreen('overview')});

document.getElementById('addTripBtn').onclick=()=>{document.getElementById('tripForm').reset();document.getElementById('tripDialog').showModal()};document.getElementById('tripForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const name=document.getElementById('tripName').value.trim();if(!name)return;state.trips.push({id:id(),name,currency:document.getElementById('tripCurrency').value,partners:['Me'],expenses:[],settlements:[]});save();e.target.reset()});
document.getElementById('editTripForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const t=state.trips.find(x=>x.id===document.getElementById('editTripId').value);if(!t)return;const newCurrency=document.getElementById('editTripCurrency').value;if(newCurrency!==t.currency&&(t.expenses.length||(t.settlements||[]).length)&&!confirm('Changing currency will relabel existing trip amounts without converting them. Continue?')){e.preventDefault();return}const entered=document.getElementById('editTripPartners').value.split(',').map(x=>x.trim()).filter(Boolean).filter(x=>x!=='Me');const used=new Set(['Me']);t.expenses.forEach(x=>{used.add(x.paidBy);(x.sharedBy||[]).forEach(p=>used.add(p))});(t.settlements||[]).forEach(x=>{used.add(x.from);used.add(x.to)});t.name=document.getElementById('editTripName').value.trim();t.currency=newCurrency;t.partners=[...new Set(['Me',...entered,...[...used].filter(x=>x!=='Me')])];save();setTimeout(()=>openTrip(t.id),0)});
document.getElementById('deleteTripBtn').onclick=()=>{const id=document.getElementById('editTripId').value,t=state.trips.find(x=>x.id===id);if(!t)return;if(confirm(`Delete ${t.name} and all linked account transactions created from this trip?`)){state.trips=state.trips.filter(x=>x.id!==id);state.transactions=state.transactions.filter(x=>x.tripId!==id);document.getElementById('editTripDialog').close();document.getElementById('tripDetail').classList.add('hidden');save()}};
document.getElementById('tripExpenseForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const t=state.trips.find(x=>x.id===document.getElementById('tripExpenseTripId').value);const shared=[...document.querySelectorAll('#tripExpenseSharedBy input:checked')].map(x=>x.value);if(!shared.length){e.preventDefault();alert('Choose at least one person to share the expense.');return}const paidBy=document.getElementById('tripExpensePaidBy').value,accountId=document.getElementById('tripExpenseAccount').value;if(accountId&&paidBy!=='Me'){e.preventDefault();alert('Only expenses paid by Me can be linked to one of your accounts. Choose “Do not link” or change Paid by to Me.');return}const expenseId=id(),amount=Number(document.getElementById('tripExpenseAmount').value),desc=document.getElementById('tripExpenseDesc').value.trim(),category=document.getElementById('tripExpenseCategory').value;t.expenses.push({id:expenseId,description:desc,amount,category,paidBy,sharedBy:shared,accountId:accountId||null});if(accountId)state.transactions.push({id:id(),type:'expense',amount,accountId,toAccountId:null,category:'Travel',date:today(),note:`${t.name}: ${desc}`,tripId:t.id,tripExpenseId:expenseId});save();setTimeout(()=>openTrip(t.id),0);e.target.reset()});
document.getElementById('settlementForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const t=state.trips.find(x=>x.id===document.getElementById('settlementTripId').value);if(!t)return;const from=document.getElementById('settlementFrom').value,to=document.getElementById('settlementTo').value,amount=Number(document.getElementById('settlementAmount').value),date=document.getElementById('settlementDate').value,accountId=document.getElementById('settlementAccount').value;if(from===to){e.preventDefault();alert('From and To must be different people.');return}if(accountId&&!['Me'].includes(from)&&!['Me'].includes(to)){e.preventDefault();alert('An account can only be linked when Me is paying or receiving.');return}const settlementId=id();t.settlements.push({id:settlementId,from,to,amount,date,accountId:accountId||null});if(accountId&&from==='Me')state.transactions.push({id:id(),type:'expense',amount,accountId,toAccountId:null,category:'Travel',date,note:`${t.name}: settlement to ${to}`,tripId:t.id,tripSettlementId:settlementId});if(accountId&&to==='Me')state.transactions.push({id:id(),type:'adjustment',direction:'in',amount,accountId,toAccountId:null,category:'Travel settlement',date,note:`${t.name}: repayment from ${from}`,tripId:t.id,tripSettlementId:settlementId});save();setTimeout(()=>openTrip(t.id),0)});

