document.getElementById('debtType').addEventListener('change',updateDebtHint);function updateDebtHint(){const type=document.getElementById('debtType').value;const el=document.getElementById('debtModeHint');if(type==='ptptn'){el.textContent='PTPTN/Ujrah estimate. The rate remains editable; check your official statement for the exact repayment schedule.';if(document.getElementById('debtRate').value==='4')document.getElementById('debtRate').value='1'}else if(type==='carFlat'){el.textContent='Legacy flat-rate estimate. Useful for older agreements, but not an early-settlement quote.'}else if(isReducing(type)){el.textContent='Reducing-balance amortisation estimate. Floating/reference-rate changes are not predicted.'}else el.textContent='Custom debt: use the rate and monthly payment from your statement.'}
document.getElementById('debtForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;const editId=document.getElementById('debtEditId').value;if(editId){const d=state.debts.find(x=>x.id===editId);const desired=Number(document.getElementById('debtOutstandingEdit').value||0);d.name=document.getElementById('debtName').value.trim();d.type=document.getElementById('debtType').value;d.currency=document.getElementById('debtCurrency').value;d.rate=Number(document.getElementById('debtRate').value||0);d.months=Number(document.getElementById('debtMonths').value||1);d.monthlyPayment=Number(document.getElementById('debtPayment').value||0);d.principal=desired+debtPrincipalPaid(d)}else{state.debts.push({id:id(),name:document.getElementById('debtName').value.trim(),type:document.getElementById('debtType').value,currency:document.getElementById('debtCurrency').value,principal:Number(document.getElementById('debtPrincipal').value),rate:Number(document.getElementById('debtRate').value||0),months:Number(document.getElementById('debtMonths').value||1),monthlyPayment:Number(document.getElementById('debtPayment').value||0),payments:[]})}save();e.target.reset()});
