// ----- v0.6 extensions -----
function homeOnlyValue(value,currency){return currency===state.settings.homeCurrency?Number(value||0):0}
function wealthNetWorth(){
  const accountNet=netWorthInHomeCurrency();
  const assets=(state.wealthAssets||[]).filter(a=>a.currency===state.settings.homeCurrency).reduce((s,a)=>s+Number(a.value||0),0);
  const debts=state.debts.filter(d=>d.currency===state.settings.homeCurrency).reduce((s,d)=>s+debtOutstanding(d),0);
  return {accountNet,assets,debts,total:accountNet+assets-debts};
}
function renderExtras(){
  renderNetWorth();renderAssets();renderFavorites();renderSearch();renderCalendar();renderRecurring();renderSubscriptions();renderPayLater();renderReminderSettings();renderCustomCategoryList();
}
function renderNetWorth(){const el=document.getElementById('accountsNetWorth');if(!el)return;const n=wealthNetWorth(),hidden=!!state.settings.netWorthHidden;el.textContent=hidden?'*****':money(n.total);const eye=document.getElementById('toggleNetWorthBtn');if(eye){eye.innerHTML=eyeIcon(hidden);eye.setAttribute('aria-label',hidden?'Show net worth':'Hide net worth')}document.getElementById('netWorthBreakdown').textContent=hidden?'Accounts + savings/investments − debts':`Accounts ${money(n.accountNet)} + savings/investments ${money(n.assets)} − debts ${money(n.debts)}`}
function renderAssets(){const el=document.getElementById('assetList');if(!el)return;el.innerHTML=(state.wealthAssets||[]).map(a=>`<button class="item" onclick="editAsset('${a.id}')"><div class="txLeft"><div class="txIcon">${a.type==='Fixed deposit'?'🏦':a.type==='Investment'?'📈':a.type==='Savings'?'💰':'💎'}</div><div><div class="title">${esc(a.name)}</div><div class="sub">${esc(a.type)}${a.institution?' · '+esc(a.institution):''}${a.maturity?' · matures '+esc(a.maturity):''}</div></div></div><div class="amount positive">${money(a.value,a.currency)}</div></button>`).join('')||'<div class="item"><div class="sub">No standalone savings or investments yet.</div></div>'}
window.editAsset=function(idv){const a=state.wealthAssets.find(x=>x.id===idv);if(!a)return;document.getElementById('assetDialogTitle').textContent='Edit savings / investment';document.getElementById('assetEditId').value=a.id;document.getElementById('assetName').value=a.name;document.getElementById('assetType').value=a.type;document.getElementById('assetCurrency').value=a.currency;document.getElementById('assetValue').value=a.value;document.getElementById('assetInstitution').value=a.institution||'';document.getElementById('assetMaturity').value=a.maturity||'';document.getElementById('deleteAssetBtn').classList.remove('hidden');document.getElementById('assetDialog').showModal()}
function renderRecurringCategoryOptions(){const type=document.getElementById('recurringType')?.value||'expense',el=document.getElementById('recurringCategory');if(el)el.innerHTML=getCategories(type).map(c=>`<option>${esc(c)}</option>`).join('')}
function renderSubscriptionCategoryOptions(){const el=document.getElementById('subscriptionCategory');if(el)el.innerHTML=getCategories('expense').map(c=>`<option>${esc(c)}</option>`).join('')}
function renderRecurring(){const el=document.getElementById('recurringList');if(!el)return;el.innerHTML=(state.recurring||[]).map(r=>`<button class="item" onclick="editRecurring('${r.id}')"><div class="txLeft"><div class="txIcon">↻</div><div><div class="title">${esc(r.name)}</div><div class="sub">${esc(r.frequency)} · next ${esc(r.nextDate)} · ${r.auto?'auto':'manual'}</div></div></div><div class="amount ${r.type==='income'?'positive':'negative'}">${money(r.amount,state.accounts.find(a=>a.id===r.accountId)?.currency||state.settings.homeCurrency)}</div></button>`).join('')||'<div class="item"><div class="sub">No recurring transactions yet.</div></div>'}
