function renderPayLater(){const el=document.getElementById('payLaterList');if(!el)return;const plans=[...(state.payLaterPlans||[])].sort((a,b)=>(a.dueDate||'').localeCompare(b.dueDate||''));el.innerHTML=plans.map(p=>{const a=state.accounts.find(x=>x.id===p.accountId),over=!p.paid&&p.dueDate<today(),soon=!p.paid&&p.dueDate>=today()&&p.dueDate<=addDays(today(),3);return `<button class="item" onclick="editPayLater('${p.id}')"><div class="txLeft"><div class="txIcon">${p.paid?'✓':over?'!':'◷'}</div><div><div class="title">${esc(p.name)}</div><div class="sub">${esc(a?.name||'PayLater')} · due ${esc(p.dueDate)}${p.paid?' · paid':over?' · overdue':soon?' · due soon':''}</div></div></div><div class="amount ${p.paid?'positive':'negative'}">${money(p.amount,a?.currency||state.settings.homeCurrency)}</div></button>`}).join('')||'<div class="item"><div class="sub">No PayLater instalments scheduled.</div></div>'}
window.editPayLater=function(idv){const p=state.payLaterPlans.find(x=>x.id===idv);if(!p)return;document.getElementById('payLaterEditId').value=p.id;document.getElementById('payLaterAccount').value=p.accountId;document.getElementById('payLaterName').value=p.name;document.getElementById('payLaterAmount').value=p.amount;document.getElementById('payLaterDueDate').value=p.dueDate;document.getElementById('payLaterPaid').checked=!!p.paid;document.getElementById('deletePayLaterBtn').classList.remove('hidden');document.getElementById('payLaterDialog').showModal()}
function renderFavorites(){const quick=document.getElementById('favoriteQuickList'),manage=document.getElementById('favoriteManageList');if(quick)quick.innerHTML=(state.favorites||[]).slice(0,8).map(f=>`<button class="chip" onclick="useFavorite('${f.id}')">${categoryIcon(f.category,f.type)} ${esc(f.note||f.category)} · ${money(f.amount,state.accounts.find(a=>a.id===f.accountId)?.currency||state.settings.homeCurrency)}</button>`).join('')||'<span class="sub">Save a transaction as a favourite to quick-add it here.</span>';if(manage)manage.innerHTML=(state.favorites||[]).map(f=>`<div class="item"><div><div class="title">${categoryIcon(f.category,f.type)} ${esc(f.note||f.category)}</div><div class="sub">${esc(f.type)} · ${money(f.amount,state.accounts.find(a=>a.id===f.accountId)?.currency||state.settings.homeCurrency)}</div></div><button class="danger tinyAction" onclick="deleteFavorite('${f.id}')">Delete</button></div>`).join('')||'<div class="item"><div class="sub">No favourites yet.</div></div>'}
window.useFavorite=function(idv){const f=state.favorites.find(x=>x.id===idv);if(!f)return;txType=f.type;document.querySelectorAll('#txTypeSeg button').forEach(b=>b.classList.toggle('active',b.dataset.type===txType));document.getElementById('toAccountWrap').classList.toggle('hidden',txType!=='transfer');document.getElementById('categoryWrap').classList.toggle('hidden',txType==='transfer');renderCategoryOptions();document.getElementById('txAmount').value=f.amount;document.getElementById('txAccount').value=f.accountId;document.getElementById('txCategory').value=f.category;document.getElementById('txNote').value=f.note||'';document.getElementById('txDate').value=today();setScreen('add')}
