function renderCustomCategoryList(){const el=document.getElementById('customCategoryList');if(!el)return;const all=['expense','income'].flatMap(type=>(state.customCategories?.[type]||[]).map(c=>({...c,type})));el.innerHTML=all.map(c=>`<div class="item"><div class="title">${esc(c.emoji||'•')} ${esc(c.name)} <span class="sub">(${c.type})</span></div><button class="danger tinyAction" onclick="deleteCustomCategory('${c.type}','${encodeURIComponent(c.name)}')">Delete</button></div>`).join('')||'<div class="item"><div class="sub">No custom categories yet.</div></div>'}
window.deleteCustomCategory=function(type,nameEnc){const name=decodeURIComponent(nameEnc);state.customCategories[type]=state.customCategories[type].filter(c=>c.name!==name);save()}
function txRow(t){const a=state.accounts.find(x=>x.id===t.accountId),sign=t.type==='expense'||(t.type==='adjustment'&&t.direction==='out')?'-':t.type==='income'||(t.type==='adjustment'&&t.direction==='in')?'+':'';const editable=['expense','income','transfer','adjustment'].includes(t.type);return `<button class="item transactionItem" ${editable?`onclick="editTransaction('${t.id}')"`:''}><div class="txLeft"><div class="txIcon">${categoryIcon(t.category,t.type)}</div><div><div class="title">${esc(t.note||t.category||t.type)}</div><div class="sub">${esc(t.date)} · ${esc(a?.name||'Account')} · ${esc(t.category||'')}${editable?' · tap to edit':''}</div></div></div><div class="amount ${sign==='-'?'negative':sign==='+'?'positive':''}">${sign}${money(t.amount,a?.currency||state.settings.homeCurrency)}</div></button>`}
window.editTransaction=function(txId){const t=state.transactions.find(x=>x.id===txId);if(!t)return;document.getElementById('editTxId').value=t.id;document.getElementById('editTxType').value=t.type;document.getElementById('editTxAmount').value=t.amount;renderEditTransactionFields();document.getElementById('editTxAccount').value=t.accountId||'';document.getElementById('editTxToAccount').value=t.toAccountId||'';document.getElementById('editTxCategory').value=t.category||'';document.getElementById('editTxDate').value=t.date||today();document.getElementById('editTxNote').value=t.note||'';document.getElementById('editTransactionDialog').showModal()}
function renderEditTransactionFields(){const type=document.getElementById('editTxType').value;const opts=state.accounts.map(a=>`<option value="${a.id}">${esc(a.name)} (${esc(a.currency)})</option>`).join('');document.getElementById('editTxAccount').innerHTML=opts;document.getElementById('editTxToAccount').innerHTML=opts;document.getElementById('editTxToWrap').classList.toggle('hidden',type!=='transfer');document.getElementById('editTxCategoryWrap').classList.toggle('hidden',type==='transfer'||type==='adjustment');document.getElementById('editTxDirectionWrap').classList.toggle('hidden',type!=='adjustment');if(type!=='transfer'&&type!=='adjustment')document.getElementById('editTxCategory').innerHTML=getCategories(type).map(c=>`<option>${esc(c)}</option>`).join('')}
function renderSearch(){const out=document.getElementById('searchResults');if(!out)return;const q=(document.getElementById('searchText')?.value||'').toLowerCase(),type=document.getElementById('searchType')?.value||'',account=document.getElementById('searchAccount')?.value||'',from=document.getElementById('searchFrom')?.value||'',to=document.getElementById('searchTo')?.value||'';const rows=[...state.transactions].filter(t=>(!type||t.type===type)&&(!account||t.accountId===account)&&(!from||t.date>=from)&&(!to||t.date<=to)&&(!q||`${t.note||''} ${t.category||''} ${state.accounts.find(a=>a.id===t.accountId)?.name||''} ${t.amount}`.toLowerCase().includes(q))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));out.innerHTML=rows.map(txRow).join('')||'<div class="item"><div class="sub">No matching transactions.</div></div>'}
function renderCalendar(){const grid=document.getElementById('calendarGrid');if(!grid)return;const month=document.getElementById('calendarMonth')?.value||currentMonth();if(!document.getElementById('calendarMonth').value)document.getElementById('calendarMonth').value=month;const [y,m]=month.split('-').map(Number),days=new Date(y,m,0).getDate(),first=(new Date(y,m-1,1).getDay()+6)%7;let html=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calHead">${d}</div>`).join('');for(let i=0;i<first;i++)html+='<div class="calBlank" aria-hidden="true"></div>';for(let d=1;d<=days;d++){const date=`${month}-${String(d).padStart(2,'0')}`,txs=state.transactions.filter(t=>t.date===date),hasTx=txs.length>0,isToday=date===today();html+=`<button class="calDay ${date===selectedCalendarDay?'selected':''} ${isToday?'today':''}" onclick="selectCalendarDay('${date}')" aria-label="${d} ${txs.length?`, ${txs.length} transaction${txs.length===1?'':'s'}`:', no transactions'}"><strong>${d}</strong><span class="calDotSlot">${hasTx?'<span class="calDot" aria-hidden="true"></span>':''}</span></button>`}grid.innerHTML=html;renderCalendarDay()}
function compactMoney(v){return new Intl.NumberFormat(undefined,{maximumFractionDigits:0,notation:'compact'}).format(v)}
window.selectCalendarDay=function(date){selectedCalendarDay=date;renderCalendar()}
function renderCalendarDay(){const el=document.getElementById('calendarDayList');if(!el)return;document.getElementById('calendarDayTitle').textContent=new Date(selectedCalendarDay+'T00:00:00').toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'});const txs=state.transactions.filter(t=>t.date===selectedCalendarDay);el.innerHTML=txs.map(txRow).join('')||'<div class="item"><div class="sub">No transactions on this day.</div></div>'}
function addDays(dateStr,n){const d=new Date(dateStr+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function addMonths(dateStr,n){const d=new Date(dateStr+'T12:00:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+n);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return d.toISOString().slice(0,10)}
function advanceByFrequency(dateStr,freq){return freq==='weekly'?addDays(dateStr,7):freq==='yearly'?addMonths(dateStr,12):addMonths(dateStr,1)}
function processDueItems(){let changed=false;const now=today();for(const r of state.recurring||[]){let guard=0;while(r.auto&&r.nextDate&&r.nextDate<=now&&guard++<60){state.transactions.push({id:id(),type:r.type,amount:Number(r.amount),accountId:r.accountId,toAccountId:null,category:r.category,date:r.nextDate,note:r.name,createdAt:Date.now(),recurringId:r.id});r.nextDate=advanceByFrequency(r.nextDate,r.frequency);changed=true}}for(const s of state.subscriptions||[]){let guard=0;while(s.auto&&s.nextDate&&s.nextDate<=now&&guard++<60){state.transactions.push({id:id(),type:'expense',amount:Number(s.amount),accountId:s.accountId,toAccountId:null,category:s.category||'Bills',date:s.nextDate,note:s.name,createdAt:Date.now(),subscriptionId:s.id});s.nextDate=advanceByFrequency(s.nextDate,s.frequency);changed=true}}if(changed)localStorage.setItem(STORE_KEY,JSON.stringify(state))}
function renderReminderSettings(){const enabled=document.getElementById('reminderEnabled'),time=document.getElementById('reminderTime');if(!enabled)return;enabled.value=state.settings.reminderEnabled?'on':'off';time.value=state.settings.reminderTime||'21:00';document.getElementById('reminderTimeWrap').classList.toggle('hidden',!state.settings.reminderEnabled)}
function fireLocalNotification(title,body){if(!('Notification' in window)||Notification.permission!=='granted')return;try{if(navigator.serviceWorker?.ready){navigator.serviceWorker.ready.then(reg=>reg.showNotification(title,{body,icon:'icon-192.png'})).catch(()=>{})}else new Notification(title,{body,icon:'icon-192.png'})}catch{}}
function checkLocalReminders(){const now=new Date(),day=today(),hhmm=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;if(state.settings.reminderEnabled&&hhmm>=String(state.settings.reminderTime||'21:00')&&state.settings.lastDailyReminder!==day){state.settings.lastDailyReminder=day;localStorage.setItem(STORE_KEY,JSON.stringify(state));fireLocalNotification('Pocket Ledger','Remember to record today’s transactions.')}const due=(state.payLaterPlans||[]).filter(p=>!p.paid&&p.dueDate>=day&&p.dueDate<=addDays(day,1));const key=`paylaterNotify-${day}`;if(due.length&&!localStorage.getItem(key)){localStorage.setItem(key,'1');fireLocalNotification('PayLater reminder',`${due.length} payment${due.length>1?'s':''} due by tomorrow. Open Pocket Ledger to review.`)}}
function previousMonthKey(){return shiftMonth(currentMonth(),-1)}
function isLastDayOfMonth(){const d=new Date();return d.getDate()===new Date(d.getFullYear(),d.getMonth()+1,0).getDate()}
function maybeShowMonthEnd(){let month=null;if(isLastDayOfMonth())month=currentMonth();else if(new Date().getDate()<=3)month=previousMonthKey();if(!month||state.settings.lastMonthEndShown===month)return;const txs=transactionsForMonth(month),inc=txs.filter(t=>t.type==='income').reduce((s,t)=>s+Number(t.amount),0),exp=txs.filter(t=>t.type==='expense').reduce((s,t)=>s+Number(t.amount),0),prev=transactionsForMonth(shiftMonth(month,-1)).filter(t=>t.type==='expense').reduce((s,t)=>s+Number(t.amount),0),change=prev?((exp-prev)/prev*100):null;const sums={};txs.filter(t=>t.type==='expense').forEach(t=>sums[t.category]=(sums[t.category]||0)+Number(t.amount));const top=Object.entries(sums).sort((a,b)=>b[1]-a[1])[0];const [y,m]=month.split('-');document.getElementById('monthEndBody').innerHTML=`<div class="miniSummary wide"><span>${new Date(+y,+m-1,1).toLocaleDateString(undefined,{month:'long',year:'numeric'})}</span><strong>${money(inc-exp)}</strong><small>Net income</small></div><div class="summaryGrid"><div class="miniSummary"><span>Income</span><strong class="positive">${money(inc)}</strong></div><div class="miniSummary"><span>Expenses</span><strong class="negative">${money(exp)}</strong></div></div>${top?`<div class="item"><div><div class="sub">Largest expense category</div><div class="title">${categoryIcon(top[0],'expense')} ${esc(top[0])}</div></div><strong>${money(top[1])}</strong></div>`:''}${change!==null?`<div class="item"><div class="sub">Expenses vs previous month</div><strong class="${change>0?'negative':'positive'}">${change>=0?'+':''}${change.toFixed(1)}%</strong></div>`:''}`;state.settings.lastMonthEndShown=month;localStorage.setItem(STORE_KEY,JSON.stringify(state));document.getElementById('monthEndDialog').showModal()}
function exportCsv(){const headers=['Date','Type','Amount','Currency','Account','Category','Note'];const rows=state.transactions.map(t=>{const a=state.accounts.find(x=>x.id===t.accountId);return [t.date,t.type,t.amount,a?.currency||state.settings.homeCurrency,a?.name||'',t.category||'',t.note||'']});const csv=[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`PocketLedger-transactions-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

