// ----- v1.1 information architecture + travel/account refinements -----
function migrate(raw){
  const base=defaults(); const s={...base,...raw};
  s.settings={...base.settings,...(raw.settings||{})};
  s.accounts=Array.isArray(raw.accounts)?raw.accounts:[];
  s.transactions=Array.isArray(raw.transactions)?raw.transactions:[];
  s.trips=Array.isArray(raw.trips)?raw.trips:[];
  s.debts=Array.isArray(raw.debts)?raw.debts:[];
  s.customCategories={expense:Array.isArray(raw.customCategories?.expense)?raw.customCategories.expense:[],income:Array.isArray(raw.customCategories?.income)?raw.customCategories.income:[]};
  s.recurring=Array.isArray(raw.recurring)?raw.recurring:[];
  s.subscriptions=Array.isArray(raw.subscriptions)?raw.subscriptions:[];
  s.wealthAssets=Array.isArray(raw.wealthAssets)?raw.wealthAssets:[];
  s.payLaterPlans=Array.isArray(raw.payLaterPlans)?raw.payLaterPlans:[];
  s.favorites=Array.isArray(raw.favorites)?raw.favorites:[];
  s.trips.forEach(t=>{if(!Array.isArray(t.expenses))t.expenses=[];if(!Array.isArray(t.partners)||!t.partners.length)t.partners=['Me'];if(!t.partners.includes('Me'))t.partners.unshift('Me');if(!Array.isArray(t.settlements))t.settlements=[]});
  s.debts.forEach(d=>{if(!Array.isArray(d.payments))d.payments=[]});
  // Subscriptions are now handled by Recurring. Existing subscription records are migrated once.
  for(const sub of s.subscriptions){
    if(!s.recurring.some(r=>r.migratedSubscriptionId===sub.id))s.recurring.push({id:id(),name:sub.name,type:'expense',amount:Number(sub.amount||0),accountId:sub.accountId,category:sub.category||'Bills',frequency:sub.frequency||'monthly',nextDate:sub.nextDate||today(),auto:!!sub.auto,migratedSubscriptionId:sub.id});
  }
  s.subscriptions=[];
  // Older trip settlements created ordinary expense rows. Keep their balance effect, but do not count/display them as spending.
  s.transactions.forEach(t=>{if(t.tripSettlementId){t.hiddenSettlement=true;if(t.type==='expense'){t.type='adjustment';t.direction='out';t.category='Travel settlement'}}});
  return s;
}
function visibleTransactions(){return state.transactions.filter(t=>!t.tripSettlementId&&!t.hiddenSettlement)}
function transactionsForMonth(m){return visibleTransactions().filter(t=>monthKey(t.date)===m)}
function savingsSummary(){
  const home=state.settings.homeCurrency;
  const liquid=state.accounts.filter(a=>!isLiabilityAccount(a)&&a.currency===home).reduce((s,a)=>s+accountBalance(a),0);
  const assets=(state.wealthAssets||[]).filter(a=>a.currency===home).reduce((s,a)=>s+Number(a.value||0),0);
  const accountLiabilities=state.accounts.filter(a=>isLiabilityAccount(a)&&a.currency===home).reduce((s,a)=>s+Math.max(0,accountBalance(a)),0);
  const debts=state.debts.filter(d=>d.currency===home).reduce((s,d)=>s+debtOutstanding(d),0);
  return {liquid,assets,savings:liquid+assets,accountLiabilities,debts,liabilities:accountLiabilities+debts};
}
function renderAll(){renderAccounts();renderSelectors();renderBalanceScopeSelector();renderOverview();renderTrips();renderDebts();renderInsights();renderExtras();document.getElementById('homeCurrency').value=state.settings.homeCurrency}
function renderAccounts(){
  const assets=state.accounts.filter(a=>!isLiabilityAccount(a));
  const liabilities=state.accounts.filter(isLiabilityAccount);
  document.getElementById('accountList').innerHTML=assets.map(a=>`<button class="item" onclick="openAccount('${a.id}')"><div class="txLeft"><div class="txIcon accountLogoBox">${accountLogoMarkup(a)}</div><div><div class="title">${esc(a.name)}</div><div class="sub">${esc(a.type)} · ${esc(a.currency)}</div></div></div><div class="amount">${money(accountBalance(a),a.currency)}</div></button>`).join('')||'<div class="item"><div class="sub">Add your first bank, e-wallet or cash account.</div></div>';
  const liabilityEl=document.getElementById('liabilityAccountList');
  if(liabilityEl)liabilityEl.innerHTML=liabilities.map(a=>`<button class="item" onclick="openAccount('${a.id}')"><div class="txLeft"><div class="txIcon accountLogoBox">${accountLogoMarkup(a)}</div><div><div class="title">${esc(a.name)}</div><div class="sub">${esc(a.type)} · ${esc(a.currency)}</div></div></div><div class="amount negative">${money(accountBalance(a),a.currency)}</div></button>`).join('')||'';
  const debtEl=document.getElementById('accountsDebtList');
  if(debtEl)debtEl.innerHTML=state.debts.map(d=>`<button class="item" onclick="openDebt('${d.id}')"><div class="txLeft"><div class="txIcon">💳</div><div><div class="title">${esc(d.name)}</div><div class="sub">${esc(loanTypeLabel(d.type))}</div></div></div><div class="amount negative">${money(debtOutstanding(d),d.currency)}</div></button>`).join('')||(!liabilities.length?'<div class="item"><div class="sub">No debts or PayLater balances recorded.</div></div>':'');
}
function renderNetWorth(){
  const el=document.getElementById('accountsNetWorth');if(!el)return;const n=savingsSummary(),hidden=!!state.settings.netWorthHidden;
  el.textContent=hidden?'*****':money(n.savings);const eye=document.getElementById('toggleNetWorthBtn');if(eye){eye.innerHTML=eyeIcon(hidden);eye.setAttribute('aria-label',hidden?'Show savings':'Hide savings')}
  const breakdown=document.getElementById('netWorthBreakdown');if(breakdown)breakdown.textContent=hidden?'Cash accounts + savings & investments':`Accounts ${money(n.liquid)} + savings/investments ${money(n.assets)}`;
  const liab=document.getElementById('accountsLiabilityTotal');if(liab)liab.textContent=money(n.liabilities);
  const lb=document.getElementById('accountsLiabilityBreakdown');if(lb)lb.textContent=`Debt ${money(n.debts)} + PayLater/credit ${money(n.accountLiabilities)}`;
}
function renderExtras(){renderNetWorth();renderAssets();renderFavorites();renderCalendar();renderRecurring();renderReminderSettings();renderCustomCategoryList()}
function renderOverview(){
  const hidden=!!state.settings.balancesHidden; let shownValue=0,shownCurrency=state.settings.homeCurrency;
  if(state.settings.balanceView==='account'){
    const a=state.accounts.find(x=>x.id===state.settings.balanceAccountId);
    if(a){shownValue=isLiabilityAccount(a)?-accountBalance(a):accountBalance(a);shownCurrency=a.currency}else{state.settings.balanceView='all';state.settings.balanceAccountId='';shownValue=netWorthInHomeCurrency()}
  }else shownValue=netWorthInHomeCurrency();
  document.getElementById('netBalance').textContent=hidden?'*****':money(shownValue,shownCurrency); const balEye=document.getElementById('toggleBalanceBtn');balEye.innerHTML=eyeIcon(hidden);balEye.setAttribute('aria-label',hidden?'Show balance':'Hide balance');
  const txs=transactionsForMonth(currentMonth()); const inc=txs.filter(t=>t.type==='income').reduce((s,t)=>s+Number(t.amount),0); const exp=txs.filter(t=>t.type==='expense').reduce((s,t)=>s+Number(t.amount),0);
  document.getElementById('monthIncome').textContent=money(inc); document.getElementById('monthExpense').textContent=money(exp);
  const [y,m]=currentMonth().split('-'); document.getElementById('monthLabel').textContent=new Date(Number(y),Number(m)-1,1).toLocaleDateString(undefined,{month:'long',year:'numeric'});
  const sums={};txs.filter(t=>t.type==='expense').forEach(t=>sums[t.category]=(sums[t.category]||0)+Number(t.amount));const max=Math.max(1,...Object.values(sums));
  document.getElementById('categorySummary').innerHTML=Object.entries(sums).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="item"><div class="txLeft" style="flex:1"><div class="txIcon">${categoryIcon(k,'expense')}</div><div style="flex:1"><div class="title">${esc(k)}</div><div class="bar"><span style="width:${v/max*100}%"></span></div></div></div><div class="amount" style="margin-left:12px">${money(v)}</div></div>`).join('')||'<div class="item"><div class="sub">No expenses this month yet.</div></div>';
  const recent=[...visibleTransactions()].sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(Number(b.createdAt||0)-Number(a.createdAt||0))).slice(0,8);
  document.getElementById('recentList').innerHTML=recent.map(txRow).join('')||'<div class="item"><div class="sub">No transactions yet.</div></div>';
}
function txRow(t){
  const a=state.accounts.find(x=>x.id===t.accountId),sign=t.type==='expense'||(t.type==='adjustment'&&t.direction==='out')?'−':t.type==='income'||(t.type==='adjustment'&&t.direction==='in')?'+':'';
  const editable=['expense','income','transfer','adjustment'].includes(t.type)&&!t.tripSettlementId;
  return `<button class="item transactionItem" ${editable?`onclick="editTransaction('${t.id}')"`:''}><div class="txLeft"><div class="txIcon">${categoryIcon(t.category,t.type)}</div><div class="txText"><div class="title">${esc(t.note||t.category||t.type)}</div><div class="sub">${esc(t.date)} · ${esc(a?.name||'Account')} · ${esc(t.category||'')}</div></div></div><div class="amount signedAmount ${sign==='−'?'negative':sign==='+'?'positive':''}">${sign}${money(t.amount,a?.currency||state.settings.homeCurrency)}</div></button>`;
}
window.openAccount=function(accountId){
  const a=state.accounts.find(x=>x.id===accountId);if(!a)return;const liability=isLiabilityAccount(a);
  const txs=visibleTransactions().filter(t=>t.accountId===a.id||t.toAccountId===a.id).sort((x,y)=>(y.date||'').localeCompare(x.date||'')||(Number(y.createdAt||0)-Number(x.createdAt||0)));
  document.getElementById('accountDetailTitle').textContent=a.name;document.getElementById('accountDetailMeta').textContent=`${a.type} · ${a.currency}`;document.getElementById('accountDetailBalance').textContent=money(accountBalance(a),a.currency);document.getElementById('accountDetailBalance').className=`balance darkBalance ${liability?'negative':''}`;
  document.getElementById('accountDetailList').innerHTML=txs.map(txRow).join('')||'<div class="item"><div class="sub">No transactions involving this account yet.</div></div>';
  document.getElementById('accountDetailEditBtn').onclick=()=>{document.getElementById('accountDetailDialog').close();editAccount(a.id)};
  const rb=document.getElementById('accountDetailReconcileBtn');if(rb)rb.onclick=()=>{document.getElementById('accountDetailDialog').close();openReconcileForAccount(a.id)};
  safeOpenDialog('accountDetailDialog');
}
function openReconcileForAccount(accountId){
  const a=state.accounts.find(x=>x.id===accountId);if(!a)return;renderSelectors();document.getElementById('reconcileAccount').value=a.id;document.getElementById('reconcileActual').value=accountBalance(a).toFixed(2);document.getElementById('reconcileDate').value=today();updateReconcileCurrent();safeOpenDialog('reconcileDialog');
}
function tripPersonNet(t,person){
  let paid=t.expenses.filter(e=>e.paidBy===person).reduce((s,e)=>s+Number(e.amount),0);
  let share=t.expenses.reduce((s,e)=>{if(!(e.sharedBy||[]).includes(person))return s;return s+Number(e.amount)/Math.max(1,(e.sharedBy||[]).length)},0);
  let net=paid-share;(t.settlements||[]).forEach(x=>{if(x.from===person)net+=Number(x.amount);if(x.to===person)net-=Number(x.amount)});return net;
}
window.openTrip=function(tripId){
  const t=state.trips.find(x=>x.id===tripId);if(!t)return;const total=t.expenses.reduce((s,e)=>s+Number(e.amount),0);const byCat={};t.expenses.forEach(e=>byCat[e.category]=(byCat[e.category]||0)+Number(e.amount));const d=document.getElementById('tripDetail');d.classList.remove('hidden');
  d.innerHTML=`<div class="sectionHead"><div><h2>${esc(t.name)}</h2><div class="sub">${t.partners.map(esc).join(' · ')}</div></div><div class="row"><button class="secondary small" onclick="editTrip('${t.id}')">Edit</button><button class="primary small" onclick="addTripExpense('${t.id}')">+ Expense</button></div></div><div class="card"><div class="muted">Trip total</div><div class="balance darkBalance">${money(total,t.currency)}</div><div class="tripTotals">${Object.entries(byCat).map(([k,v])=>`<button class="miniCard tripCategoryCard" onclick="openTripCategory('${t.id}','${encodeURIComponent(k)}')"><div class="muted">${esc(k)}</div><strong>${money(v,t.currency)}</strong><span class="miniChevron">›</span></button>`).join('')||'<div class="sub">No spending yet.</div>'}</div></div><div class="sectionHead"><h2>By person</h2></div><div class="stack">${t.partners.map(p=>{const net=tripPersonNet(t,p);const status=net<-.01?`Pay ${money(-net,t.currency)}`:net>.01?`Receive ${money(net,t.currency)}`:'Settled';return `<button class="personSummary item" onclick="openTripPerson('${t.id}','${encodeURIComponent(p)}')"><div class="title">${esc(p)}</div><div class="right"><div class="amount ${net<-.01?'negative':net>.01?'positive':''}">${status}</div><span class="miniChevron">›</span></div></button>`}).join('')}</div><div class="sectionHead"><h2>Expenses</h2></div><div class="stack">${t.expenses.map(e=>`<div class="item"><div class="txLeft"><div class="txIcon">${categoryIcon(e.category,'expense')}</div><div><div class="title">${esc(e.description)}</div><div class="sub">${esc(e.category)} · paid by ${esc(e.paidBy)}${e.accountId?' · linked':''}</div></div></div><div class="amount">${money(e.amount,t.currency)}</div></div>`).join('')||'<div class="item"><div class="sub">No trip expenses yet.</div></div>'}</div>`;d.scrollIntoView({behavior:'smooth'});
}
window.openTripCategory=function(tripId,catEnc){
  const t=state.trips.find(x=>x.id===tripId),cat=decodeURIComponent(catEnc);if(!t)return;const rows=t.expenses.filter(e=>e.category===cat),total=rows.reduce((s,e)=>s+Number(e.amount),0);
  document.getElementById('tripCategoryTitle').textContent=cat;document.getElementById('tripCategoryTotal').textContent=`${money(total,t.currency)} total`;
  document.getElementById('tripCategoryList').innerHTML=rows.map(e=>`<div class="item"><div class="txLeft"><div class="txIcon">${categoryIcon(e.category,'expense')}</div><div><div class="title">${esc(e.description)}</div><div class="sub">Paid by ${esc(e.paidBy)} · shared by ${(e.sharedBy||[]).map(esc).join(', ')}</div></div></div><div class="amount">${money(e.amount,t.currency)}</div></div>`).join('')||'<div class="item"><div class="sub">No expenses in this category.</div></div>';
  safeOpenDialog('tripCategoryDialog');
}
window.openTripPerson=function(tripId,personEnc){
  const t=state.trips.find(x=>x.id===tripId),person=decodeURIComponent(personEnc);if(!t)return;const net=tripPersonNet(t,person),suggestions=tripSettlementSuggestions(t).filter(x=>x.from===person||x.to===person);
  document.getElementById('tripPersonTitle').textContent=person;document.getElementById('tripPersonStatus').textContent=net<-.01?`Needs to pay ${money(-net,t.currency)}`:net>.01?`Needs to receive ${money(net,t.currency)}`:'Fully settled';
  document.getElementById('tripPersonObligations').innerHTML=suggestions.map(x=>{const paying=x.from===person;return `<button class="item settlementAction" onclick="document.getElementById('tripPersonDialog').close();openSettlement('${t.id}','${encodeURIComponent(x.from)}','${encodeURIComponent(x.to)}',${Number(x.amount)})"><div><div class="title">${paying?`Pay ${esc(x.to)}`:`Receive from ${esc(x.from)}`}</div><div class="sub">Tap to record settlement</div></div><div class="amount ${paying?'negative':'positive'}">${money(x.amount,t.currency)}</div></button>`}).join('')||'<div class="item"><div class="sub">No payment is currently required.</div></div>';
  const rows=t.expenses.filter(e=>e.paidBy===person||(e.sharedBy||[]).includes(person));
  document.getElementById('tripPersonTransactions').innerHTML=rows.map(e=>{const roles=[];if(e.paidBy===person)roles.push('paid');if((e.sharedBy||[]).includes(person))roles.push('shared');return `<div class="item"><div class="txLeft"><div class="txIcon">${categoryIcon(e.category,'expense')}</div><div><div class="title">${esc(e.description)}</div><div class="sub">${esc(e.category)} · ${roles.join(' + ')}</div></div></div><div class="amount">${money(e.amount,t.currency)}</div></div>`}).join('')||'<div class="item"><div class="sub">No trip expenses involve this person.</div></div>';
  const settlements=(t.settlements||[]).filter(x=>x.from===person||x.to===person).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  document.getElementById('tripPersonSettlements').innerHTML=settlements.map(x=>`<div class="item"><div><div class="title">${esc(x.from)} → ${esc(x.to)}</div><div class="sub">${esc(x.date||'')}</div></div><div class="amount">${money(x.amount,t.currency)}</div></div>`).join('')||'<div class="item"><div class="sub">No settlements recorded for this person.</div></div>';
  safeOpenDialog('tripPersonDialog');
}
window.openSettlement=function(tripId,from='',to='',amount=''){
  const t=state.trips.find(x=>x.id===tripId);if(!t)return;from=decodeURIComponent(from||'');to=decodeURIComponent(to||'');const opts=t.partners.map(p=>`<option>${esc(p)}</option>`).join('');document.getElementById('settlementTripId').value=t.id;document.getElementById('settlementFrom').innerHTML=opts;document.getElementById('settlementTo').innerHTML=opts;document.getElementById('settlementFrom').value=from||t.partners[0];document.getElementById('settlementTo').value=to||t.partners.find(p=>p!==document.getElementById('settlementFrom').value)||t.partners[0];document.getElementById('settlementAmount').value=amount?Number(amount).toFixed(2):'';document.getElementById('settlementDate').value=today();renderSelectors();safeOpenDialog('settlementDialog');
}
function renderCalendar(){
  const grid=document.getElementById('calendarGrid');if(!grid)return;const month=document.getElementById('calendarMonth')?.value||currentMonth();if(!document.getElementById('calendarMonth').value)document.getElementById('calendarMonth').value=month;const [y,m]=month.split('-').map(Number),days=new Date(y,m,0).getDate(),first=(new Date(y,m-1,1).getDay()+6)%7;const visible=visibleTransactions();let html=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calHead">${d}</div>`).join('');for(let i=0;i<first;i++)html+='<div class="calBlank" aria-hidden="true"></div>';for(let d=1;d<=days;d++){const date=`${month}-${String(d).padStart(2,'0')}`,txs=visible.filter(t=>t.date===date),hasTx=txs.length>0,isToday=date===today();html+=`<button class="calDay ${date===selectedCalendarDay?'selected':''} ${isToday?'today':''}" onclick="selectCalendarDay('${date}')" aria-label="${d}${txs.length?`, ${txs.length} transaction${txs.length===1?'':'s'}`:', no transactions'}"><strong>${d}</strong><span class="calDotSlot">${hasTx?'<span class="calDot" aria-hidden="true"></span>':''}</span></button>`}grid.innerHTML=html;renderCalendarDay();
}
function renderCalendarDay(){const el=document.getElementById('calendarDayList');if(!el)return;document.getElementById('calendarDayTitle').textContent=new Date(selectedCalendarDay+'T00:00:00').toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'});const txs=visibleTransactions().filter(t=>t.date===selectedCalendarDay);el.innerHTML=txs.map(txRow).join('')||'<div class="item"><div class="sub">No transactions on this day.</div></div>'}
function processDueItems(){let changed=false;const now=today();for(const r of state.recurring||[]){let guard=0;while(r.auto&&r.nextDate&&r.nextDate<=now&&guard++<60){state.transactions.push({id:id(),type:r.type,amount:Number(r.amount),accountId:r.accountId,toAccountId:null,category:r.category,date:r.nextDate,note:r.name,createdAt:Date.now(),recurringId:r.id});r.nextDate=advanceByFrequency(r.nextDate,r.frequency);changed=true}}if(changed)localStorage.setItem(STORE_KEY,JSON.stringify(state))}

// Settlement records stay in Travel > By person. Linked accounts receive a hidden balance adjustment only.
const settlementFormV11=document.getElementById('settlementForm');
if(settlementFormV11){
  const replacement=settlementFormV11.cloneNode(true);settlementFormV11.replaceWith(replacement);
  replacement.addEventListener('submit',e=>{if(e.submitter?.value==='cancel'||e.submitter?.classList.contains('dialogCancel'))return;const t=state.trips.find(x=>x.id===document.getElementById('settlementTripId').value);if(!t)return;const from=document.getElementById('settlementFrom').value,to=document.getElementById('settlementTo').value,amount=Number(document.getElementById('settlementAmount').value),date=document.getElementById('settlementDate').value,accountId=document.getElementById('settlementAccount').value;if(from===to){e.preventDefault();alert('From and To must be different people.');return}if(accountId&&from!=='Me'&&to!=='Me'){e.preventDefault();alert('An account can only be linked when Me is paying or receiving.');return}const settlementId=id();t.settlements.push({id:settlementId,from,to,amount,date,accountId:accountId||null});if(accountId&&from==='Me')state.transactions.push({id:id(),type:'adjustment',direction:'out',amount,accountId,toAccountId:null,category:'Travel settlement',date,note:`${t.name}: settlement to ${to}`,tripId:t.id,tripSettlementId:settlementId,hiddenSettlement:true});if(accountId&&to==='Me')state.transactions.push({id:id(),type:'adjustment',direction:'in',amount,accountId,toAccountId:null,category:'Travel settlement',date,note:`${t.name}: repayment from ${from}`,tripId:t.id,tripSettlementId:settlementId,hiddenSettlement:true});save();setTimeout(()=>{openTrip(t.id);openTripPerson(t.id,encodeURIComponent(from==='Me'?to:from))},0)});
}
const addDebtFromAccountsBtn=document.getElementById('addDebtFromAccountsBtn');if(addDebtFromAccountsBtn)addDebtFromAccountsBtn.onclick=()=>document.getElementById('addDebtBtn').click();
