const settlementCancelV11=document.querySelector('#settlementForm .dialogCancel');if(settlementCancelV11)settlementCancelV11.addEventListener('click',()=>document.getElementById('settlementDialog')?.close());
function exportCsv(){const headers=['Date','Type','Amount','Currency','Account','Category','Note'];const rows=visibleTransactions().map(t=>{const a=state.accounts.find(x=>x.id===t.accountId);return [t.date,t.type,t.amount,a?.currency||state.settings.homeCurrency,a?.name||'',t.category||'',t.note||'']});const csv=[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`PocketLedger-transactions-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
